import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Settings, 
  Plus, 
  Edit, 
  Trash2, 
  Save, 
  X,
  List,
  Tag,
  Users,
  Building,
  Award,
  Database,
  Download,
  Upload,
  RefreshCw
} from 'lucide-react';
import { 
  getDepartments,
  addDepartment,
  updateDepartment,
  deleteDepartment,
  clearAllData,
  getStatistics
} from '../lib/database';
import { useToast } from '../hooks/use-toast';

// System configuration options
const STATUS_OPTIONS = [
  { id: 'completed', name: 'مكتملة', color: 'green' },
  { id: 'in_progress', name: 'قيد التنفيذ', color: 'yellow' },
  { id: 'delayed', name: 'متأخرة', color: 'red' },
  { id: 'not_started', name: 'لم تبدأ', color: 'gray' }
];

const PRIORITY_OPTIONS = [
  { id: 'high', name: 'عالية', color: 'red' },
  { id: 'medium', name: 'متوسطة', color: 'yellow' },
  { id: 'low', name: 'منخفضة', color: 'green' }
];

const AWARD_CRITERIA = [
  { id: 'enablers', name: 'الممكنات', category: 'أساسية' },
  { id: 'leadership', name: 'القيادة والحوكمة', category: 'أساسية' },
  { id: 'strategy', name: 'الاستراتيجية والتخطيط', category: 'أساسية' },
  { id: 'operations', name: 'العمليات والخدمات', category: 'أساسية' },
  { id: 'hr', name: 'الموارد البشرية', category: 'أساسية' },
  { id: 'partnerships', name: 'الشراكات والموارد', category: 'أساسية' },
  { id: 'knowledge', name: 'المعرفة والابتكار', category: 'أساسية' },
  { id: 'results', name: 'النتائج والأداء', category: 'نتائج' },
  { id: 'satisfaction', name: 'رضا المتعاملين', category: 'نتائج' },
  { id: 'social', name: 'المسؤولية المجتمعية', category: 'نتائج' }
];

function SiteAdministration({ open, onOpenChange }) {
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState('departments');
  const [departments, setDepartments] = useState([]);
  const [statistics, setStatistics] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  
  // Form states
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState({});

  useEffect(() => {
    if (open) {
      loadData();
    }
  }, [open]);

  const loadData = async () => {
    try {
      setIsLoading(true);
      const [departmentsData, statsData] = await Promise.all([
        getDepartments(),
        getStatistics()
      ]);
      setDepartments(departmentsData);
      setStatistics(statsData);
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل البيانات",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddDepartment = () => {
    setEditingId(null);
    setFormData({
      name: '',
      manager: '',
      employee_count: 0,
      budget: 0,
      description: ''
    });
    setShowAddForm(true);
  };

  const handleEditDepartment = (dept) => {
    setEditingId(dept.id);
    setFormData({ ...dept });
    setShowAddForm(true);
  };

  const handleSaveDepartment = async () => {
    try {
      if (editingId) {
        await updateDepartment(editingId, formData);
        toast({
          title: "تم التحديث",
          description: "تم تحديث الإدارة بنجاح",
        });
      } else {
        await addDepartment(formData);
        toast({
          title: "تم الحفظ",
          description: "تم إضافة الإدارة بنجاح",
        });
      }
      await loadData();
      setShowAddForm(false);
      setEditingId(null);
      setFormData({});
    } catch (error) {
      console.error('Error saving department:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حفظ الإدارة",
        variant: "destructive",
      });
    }
  };

  const handleDeleteDepartment = async (id) => {
    if (!confirm('هل أنت متأكد من حذف هذه الإدارة؟ سيؤثر هذا على جميع المبادرات المرتبطة بها.')) return;
    
    try {
      await deleteDepartment(id);
      await loadData();
      toast({
        title: "تم الحذف",
        description: "تم حذف الإدارة بنجاح",
      });
    } catch (error) {
      console.error('Error deleting department:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف الإدارة",
        variant: "destructive",
      });
    }
  };

  const handleClearAllData = async () => {
    if (!confirm('تحذير: هذا الإجراء سيحذف جميع البيانات نهائياً. هل أنت متأكد؟')) return;
    if (!confirm('تأكيد أخير: سيتم حذف جميع المبادرات ونقاط الجائزة والإدارات. هل تريد المتابعة؟')) return;
    
    try {
      setIsLoading(true);
      await clearAllData();
      await loadData();
      toast({
        title: "تم المسح",
        description: "تم مسح جميع البيانات بنجاح",
      });
    } catch (error) {
      console.error('Error clearing data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في مسح البيانات",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const exportSystemConfig = () => {
    const config = {
      departments: departments,
      statusOptions: STATUS_OPTIONS,
      priorityOptions: PRIORITY_OPTIONS,
      awardCriteria: AWARD_CRITERIA,
      exportDate: new Date().toISOString()
    };
    
    const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `system-config-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    
    toast({
      title: "تم التصدير",
      description: "تم تصدير إعدادات النظام بنجاح",
    });
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-6xl max-h-[90vh] overflow-hidden">
        <div className="flex items-center justify-between p-6 border-b border-gray-200">
          <h2 className="text-xl font-bold flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Settings className="h-5 w-5" />
            إدارة الموقع والإعدادات
          </h2>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
          >
            <X className="h-4 w-4" />
          </Button>
        </div>

        <div className="p-6 overflow-y-auto max-h-[calc(90vh-120px)]">
          {isLoading ? (
            <div className="flex items-center justify-center h-64">
              <div className="text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600 mx-auto mb-4"></div>
                <p className="text-gray-600">جاري تحميل البيانات...</p>
              </div>
            </div>
          ) : (
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabsList className="grid w-full grid-cols-4">
                <TabsTrigger value="departments" className="flex items-center gap-2">
                  <Building className="h-4 w-4" />
                  الإدارات
                </TabsTrigger>
                <TabsTrigger value="options" className="flex items-center gap-2">
                  <List className="h-4 w-4" />
                  الخيارات
                </TabsTrigger>
                <TabsTrigger value="statistics" className="flex items-center gap-2">
                  <Database className="h-4 w-4" />
                  الإحصائيات
                </TabsTrigger>
                <TabsTrigger value="system" className="flex items-center gap-2">
                  <Settings className="h-4 w-4" />
                  النظام
                </TabsTrigger>
              </TabsList>

              {/* Departments Management */}
              <TabsContent value="departments" className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-lg font-semibold">إدارة الإدارات ({departments.length})</h3>
                  <Button
                    onClick={handleAddDepartment}
                    style={{backgroundColor: 'var(--brand-orange)'}}
                    className="text-white"
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    إضافة إدارة جديدة
                  </Button>
                </div>

                {showAddForm && (
                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg">
                        {editingId ? 'تحرير الإدارة' : 'إضافة إدارة جديدة'}
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">اسم الإدارة *</label>
                          <Input
                            value={formData.name || ''}
                            onChange={(e) => setFormData({...formData, name: e.target.value})}
                            placeholder="أدخل اسم الإدارة"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">المدير</label>
                          <Input
                            value={formData.manager || ''}
                            onChange={(e) => setFormData({...formData, manager: e.target.value})}
                            placeholder="أدخل اسم المدير"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">عدد الموظفين</label>
                          <Input
                            type="number"
                            value={formData.employee_count || 0}
                            onChange={(e) => setFormData({...formData, employee_count: parseInt(e.target.value) || 0})}
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">الميزانية (د.إ)</label>
                          <Input
                            type="number"
                            value={formData.budget || 0}
                            onChange={(e) => setFormData({...formData, budget: parseFloat(e.target.value) || 0})}
                          />
                        </div>
                        <div className="md:col-span-2">
                          <label className="block text-sm font-medium text-gray-700 mb-1">الوصف</label>
                          <Textarea
                            value={formData.description || ''}
                            onChange={(e) => setFormData({...formData, description: e.target.value})}
                            placeholder="أدخل وصف الإدارة"
                            rows={3}
                          />
                        </div>
                      </div>
                      <div className="flex justify-end gap-2 mt-4">
                        <Button variant="outline" onClick={() => setShowAddForm(false)}>
                          <X className="h-4 w-4 mr-2" />
                          إلغاء
                        </Button>
                        <Button onClick={handleSaveDepartment} style={{backgroundColor: 'var(--brand-orange)'}} className="text-white">
                          <Save className="h-4 w-4 mr-2" />
                          حفظ
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                )}

                <Card>
                  <CardContent className="p-0">
                    <div className="overflow-x-auto">
                      <table className="w-full border-collapse">
                        <thead>
                          <tr className="border-b border-gray-200 bg-gray-50">
                            <th className="text-right p-3 font-medium text-gray-700">الرقم</th>
                            <th className="text-right p-3 font-medium text-gray-700">اسم الإدارة</th>
                            <th className="text-right p-3 font-medium text-gray-700">المدير</th>
                            <th className="text-center p-3 font-medium text-gray-700">عدد الموظفين</th>
                            <th className="text-center p-3 font-medium text-gray-700">الميزانية</th>
                            <th className="text-center p-3 font-medium text-gray-700">الإجراءات</th>
                          </tr>
                        </thead>
                        <tbody>
                          {departments.map((dept, index) => (
                            <tr key={dept.id} className="border-b border-gray-100 hover:bg-gray-50">
                              <td className="p-3 text-sm">{index + 1}</td>
                              <td className="p-3">
                                <div className="font-medium text-sm">{dept.name}</div>
                                {dept.description && (
                                  <div className="text-xs text-gray-500 mt-1">{dept.description}</div>
                                )}
                              </td>
                              <td className="p-3 text-sm">{dept.manager || '-'}</td>
                              <td className="p-3 text-center text-sm">{dept.employee_count || 0}</td>
                              <td className="p-3 text-center text-sm">
                                {dept.budget ? `${dept.budget.toLocaleString()} د.إ` : '-'}
                              </td>
                              <td className="p-3 text-center">
                                <div className="flex items-center justify-center gap-1">
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={() => handleEditDepartment(dept)}
                                    className="h-8 w-8 p-0"
                                  >
                                    <Edit className="h-3 w-3" />
                                  </Button>
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={() => handleDeleteDepartment(dept.id)}
                                    className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                                  >
                                    <Trash2 className="h-3 w-3" />
                                  </Button>
                                </div>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                      {departments.length === 0 && (
                        <div className="text-center py-8">
                          <Building className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                          <p className="text-gray-500">لا توجد إدارات مضافة</p>
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </TabsContent>

              {/* System Options */}
              <TabsContent value="options" className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg flex items-center gap-2">
                        <Tag className="h-4 w-4" />
                        حالات المبادرات
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2">
                        {STATUS_OPTIONS.map(status => (
                          <div key={status.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                            <span className="text-sm">{status.name}</span>
                            <Badge className={`bg-${status.color}-100 text-${status.color}-800 text-xs`}>
                              {status.color}
                            </Badge>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>

                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg flex items-center gap-2">
                        <Users className="h-4 w-4" />
                        مستويات الأولوية
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2">
                        {PRIORITY_OPTIONS.map(priority => (
                          <div key={priority.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                            <span className="text-sm">{priority.name}</span>
                            <Badge className={`bg-${priority.color}-100 text-${priority.color}-800 text-xs`}>
                              {priority.color}
                            </Badge>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>

                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg flex items-center gap-2">
                        <Award className="h-4 w-4" />
                        معايير الجائزة
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2 max-h-64 overflow-y-auto">
                        {AWARD_CRITERIA.map(criteria => (
                          <div key={criteria.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                            <div>
                              <div className="text-sm font-medium">{criteria.name}</div>
                              <div className="text-xs text-gray-500">{criteria.category}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                </div>
              </TabsContent>

              {/* Statistics */}
              <TabsContent value="statistics" className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  <Card>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-2 mb-2">
                        <Building className="h-4 w-4" style={{color: 'var(--brand-orange)'}} />
                        <span className="text-sm font-medium text-gray-600">إجمالي المبادرات</span>
                      </div>
                      <div className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>
                        {statistics.totalInitiatives || 0}
                      </div>
                    </CardContent>
                  </Card>

                  <Card>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-2 mb-2">
                        <Users className="h-4 w-4 text-green-600" />
                        <span className="text-sm font-medium text-gray-600">الإدارات النشطة</span>
                      </div>
                      <div className="text-2xl font-bold text-green-600">
                        {statistics.activeDepartments || 0}
                      </div>
                    </CardContent>
                  </Card>

                  <Card>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-2 mb-2">
                        <Award className="h-4 w-4 text-blue-600" />
                        <span className="text-sm font-medium text-gray-600">نقاط الجائزة</span>
                      </div>
                      <div className="text-2xl font-bold text-blue-600">
                        {statistics.totalAwardPoints || 0}
                      </div>
                    </CardContent>
                  </Card>

                  <Card>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-2 mb-2">
                        <Database className="h-4 w-4 text-purple-600" />
                        <span className="text-sm font-medium text-gray-600">معدل الأداء</span>
                      </div>
                      <div className="text-2xl font-bold text-purple-600">
                        {Math.round(statistics.performanceScore || 0)}%
                      </div>
                    </CardContent>
                  </Card>
                </div>

                <Card>
                  <CardHeader>
                    <CardTitle>تفاصيل الإحصائيات</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <h4 className="font-medium mb-2">حالة المبادرات</h4>
                        <div className="space-y-2">
                          <div className="flex justify-between">
                            <span className="text-sm">مكتملة</span>
                            <span className="text-sm font-medium">{statistics.completedInitiatives || 0}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm">قيد التنفيذ</span>
                            <span className="text-sm font-medium">{statistics.inProgressInitiatives || 0}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm">متأخرة</span>
                            <span className="text-sm font-medium">{statistics.delayedInitiatives || 0}</span>
                          </div>
                        </div>
                      </div>
                      <div>
                        <h4 className="font-medium mb-2">نقاط الجائزة</h4>
                        <div className="space-y-2">
                          <div className="flex justify-between">
                            <span className="text-sm">نقاط القوة</span>
                            <span className="text-sm font-medium">{statistics.strengthPoints || 0}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm">نقاط التحسين</span>
                            <span className="text-sm font-medium">{statistics.improvementPoints || 0}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-sm">نسبة الإكمال</span>
                            <span className="text-sm font-medium">{Math.round(statistics.completionPercentage || 0)}%</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </TabsContent>

              {/* System Management */}
              <TabsContent value="system" className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg flex items-center gap-2">
                        <Download className="h-4 w-4" />
                        تصدير الإعدادات
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <p className="text-sm text-gray-600 mb-4">
                        تصدير إعدادات النظام والإدارات والخيارات المتاحة
                      </p>
                      <Button
                        onClick={exportSystemConfig}
                        className="w-full"
                        style={{backgroundColor: 'var(--brand-orange)'}}
                      >
                        <Download className="h-4 w-4 mr-2" />
                        تصدير الإعدادات
                      </Button>
                    </CardContent>
                  </Card>

                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg flex items-center gap-2">
                        <RefreshCw className="h-4 w-4" />
                        تحديث البيانات
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <p className="text-sm text-gray-600 mb-4">
                        إعادة تحميل جميع البيانات من قاعدة البيانات المحلية
                      </p>
                      <Button
                        onClick={loadData}
                        variant="outline"
                        className="w-full"
                        disabled={isLoading}
                      >
                        <RefreshCw className={`h-4 w-4 mr-2 ${isLoading ? 'animate-spin' : ''}`} />
                        تحديث البيانات
                      </Button>
                    </CardContent>
                  </Card>

                  <Card className="md:col-span-2">
                    <CardHeader>
                      <CardTitle className="text-lg flex items-center gap-2 text-red-600">
                        <Trash2 className="h-4 w-4" />
                        منطقة الخطر
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                        <h4 className="font-medium text-red-800 mb-2">مسح جميع البيانات</h4>
                        <p className="text-sm text-red-600 mb-4">
                          تحذير: هذا الإجراء سيحذف جميع المبادرات ونقاط الجائزة والإدارات نهائياً ولا يمكن التراجع عنه.
                        </p>
                        <Button
                          onClick={handleClearAllData}
                          variant="destructive"
                          disabled={isLoading}
                        >
                          <Trash2 className="h-4 w-4 mr-2" />
                          مسح جميع البيانات
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                </div>
              </TabsContent>
            </Tabs>
          )}
        </div>
      </div>
    </div>
  );
}

export default SiteAdministration;
